import express, { Express } from 'express';
import { InMemoryUserRepository } from './repositories/InMemoryUserRepository';
import { InMemoryProjectRepository } from './repositories/InMemoryProjectRepository';
import { InMemoryTaskRepository } from './repositories/InMemoryTaskRepository';
import { ProjectController } from './controllers/ProjectController';
import { TaskController } from './controllers/TaskController';
import { CreateProjectUseCase } from '../application/usecases/CreateProjectUseCase';
import { CreateTaskUseCase } from '../application/usecases/CreateTaskUseCase';
import { AssignTaskUseCase } from '../application/usecases/AssignTaskUseCase';
import { MarkTaskAsDoneUseCase } from '../application/usecases/MarkTaskAsDoneUseCase';
import { ListTasksUseCase } from '../application/usecases/ListTasksUseCase';
import { User } from '../domain/entities/User';

export function createApp(): Express {
  const app = express();

  app.use(express.json());

  const userRepository = new InMemoryUserRepository();
  const projectRepository = new InMemoryProjectRepository();
  const taskRepository = new InMemoryTaskRepository();

  seedUsers(userRepository);

  const createProjectUseCase = new CreateProjectUseCase(projectRepository);
  const createTaskUseCase = new CreateTaskUseCase(
    taskRepository,
    projectRepository,
  );
  const assignTaskUseCase = new AssignTaskUseCase(
    taskRepository,
    userRepository,
  );
  const markTaskAsDoneUseCase = new MarkTaskAsDoneUseCase(taskRepository);
  const listTasksUseCase = new ListTasksUseCase(taskRepository);

  const projectController = new ProjectController(createProjectUseCase);
  const taskController = new TaskController(
    createTaskUseCase,
    assignTaskUseCase,
    markTaskAsDoneUseCase,
    listTasksUseCase,
  );

  app.post('/projects', (req, res) => projectController.createProject(req, res));
  app.post('/tasks', (req, res) => taskController.createTask(req, res));
  app.post('/tasks/assign', (req, res) => taskController.assignTask(req, res));
  app.post('/tasks/done', (req, res) =>
    taskController.markTaskAsDone(req, res),
  );
  app.get('/projects/:projectId/tasks', (req, res) =>
    taskController.listTasks(req, res),
  );

  return app;
}

function seedUsers(userRepository: InMemoryUserRepository): void {
  const users = [
    new User('user_1', 'alice', 'alice@example.com'),
    new User('user_2', 'bob', 'bob@example.com'),
    new User('user_3', 'charlie', 'charlie@example.com'),
  ];

  users.forEach((user) => userRepository.save(user));
}

